import math
cnt = {("1","1R"):40, ("1","2LDK"):10, ("2+","1R"):5, ("2+","2LDK"):45}
def mi(cnt):
    N = sum(cnt.values()); px = {}; py = {}
    for (x, y), c in cnt.items():
        px[x] = px.get(x, 0) + c; py[y] = py.get(y, 0) + c
    return sum(c/N*math.log2((c/N)/((px[x]/N)*(py[y]/N))) for (x, y), c in cnt.items())
print(round(mi(cnt), 3))                       # 0.397
print(round(mi({k: 25 for k in cnt}), 3))      # 0.0

import math
def dcg(r): return sum(x/math.log2(i+2) for i, x in enumerate(r))
def ndcg(ranked, rel, k=3):
    got = [rel.get(x, 0) for x in ranked[:k]]
    return dcg(got) / dcg(sorted(rel.values(), reverse=True)[:k])
rel = {"A":3, "B":2, "C":0, "D":1, "E":0}
print(round(ndcg(["C","A","D","B","E"], rel), 3))  # 0.502
print(round(ndcg(["A","B","D","C","E"], rel), 3))  # 1.0
